// ─── Anpassen ───────────────────────────────────────────────
const SITE_URL = 'https://taswiq-media.de';
const CALENDLY_URL = 'https://calendly.com/DEIN-NAME/erstgespraech';
const PHONE = '+49 162 2035499';
const WHATSAPP = 'https://wa.me/491622035499';
// ────────────────────────────────────────────────────────────

const input = $input.first().json;
const payload = input.body ?? input;          // Webhook v2 legt den Body unter .body ab
const lead = payload.lead;
if (!lead?.email) throw new Error('Payload ohne lead.email – falsche Quelle?');

const eur = (n) => new Intl.NumberFormat('de-DE').format(n) + ' €';
const INDUSTRY = { gastro: 'Gastronomie', musik: 'Festival & Musik', andere: 'Andere Branche' };
const BUDGET = { unter_1k: 'unter 1.000 €', '1k_2_5k': '1.000–2.500 €', '2_5k_5k': '2.500–5.000 €', ueber_5k: 'über 5.000 €', keine_angabe: 'keine Angabe' };
const TIER = { starter: 'Starter', growth: 'Growth', premium: 'PREMIUM' };
const SOURCE = { funnel: 'Funnel', rechner: 'Preisrechner', ki_seite: 'Content-Pipeline-Seite', branchen_seite: 'SEO-Seite' };

// Branchen-Intro – personalisierter Einstieg der Willkommens-Mail
const INTRO = {
  gastro: 'danke für deine Anfrage! Wir lieben Küchen, in denen es zischt, und Gäste, die ihr Handy zücken, bevor sie essen. Genau diese Momente machen wir zu Content, der Tische füllt.',
  musik: 'danke für deine Anfrage! Nichts verkauft das nächste Event besser als ein Aftermovie, das den Abend zurückholt – und Clips, die schon während des Vorverkaufs laufen.',
  andere: 'danke für deine Anfrage! Wir schauen uns dein Vorhaben genau an und melden uns mit einem konkreten Vorschlag.',
};

const STARTER = {
  gastro: [['Digitale Speisekarte', '199 €'], ['Food-Foto Express', '390 €'], ['Reels aus deinem Material', '490 €']],
  musik: [['KI-Visualizer', '290 €'], ['Artist-Shooting', '390 €'], ['Promo-Kit', '390 €']],
  andere: [['Foto Express', '390 €'], ['Reels aus deinem Material', '490 €'], ['KI-Workflow Starter', '490 €']],
};

const btn = (href, label) => `<a href="${href}" style="display:inline-block;background:#5aaeb8;color:#0f1720;font-weight:700;text-decoration:none;padding:14px 26px;border-radius:999px">${label}</a>`;

let subject, body;
if (lead.tier === 'starter') {
  subject = `${lead.firstName}, hier sind deine Starter-Pakete`;
  const rows = STARTER[lead.industry].map(([n, p]) => `<tr><td style="padding:10px 0;border-bottom:1px solid #dfe4ea;font-weight:700;color:#1c2631">${n}</td><td style="padding:10px 0;border-bottom:1px solid #dfe4ea;text-align:right;font-weight:800;color:#1c2631">${p}</td></tr>`).join('');
  body = `<p>Für dein Budget sind unsere festen Pakete ideal – kein Erstgespräch nötig, Start innerhalb weniger Tage:</p>
<table width="100%" cellpadding="0" cellspacing="0" style="margin:18px 0">${rows}</table>
<p>Antworte einfach auf diese Mail oder schreib uns per WhatsApp, welches Paket du möchtest.</p>
<p>${btn(WHATSAPP, 'Paket per WhatsApp buchen')}</p>`;
} else if (lead.tier === 'premium') {
  subject = `${lead.firstName}, lass uns direkt sprechen`;
  body = `<p>Projekte dieser Größe planen wir persönlich. Such dir einen Termin für ein 30-minütiges Strategiegespräch aus – kostenlos und unverbindlich:</p>
<p>${btn(CALENDLY_URL + '?name=' + encodeURIComponent(lead.name) + '&email=' + encodeURIComponent(lead.email), 'Termin auswählen')}</p>
<p>Lieber sofort? Ruf mich an: <a href="tel:${PHONE.replace(/\s/g, '')}" style="color:#287681;font-weight:700">${PHONE}</a></p>`;
} else {
  subject = `Dein Angebot kommt in 24 Stunden, ${lead.firstName}`;
  body = `<p>So geht es weiter:</p>
<ol style="padding-left:18px;line-height:1.7"><li>Wir prüfen deine Angaben und schauen uns deine Kanäle an.</li><li>Innerhalb von 24 Stunden bekommst du ein Angebot mit Festpreis.</li><li>Passt alles, planen wir den Deep Dive – per Call oder vor Ort.</li></ol>`;
}

const estimate = lead.estimate ? `<p style="margin:18px 0;padding:14px 18px;background:#1f2b38;color:#fff;border-radius:8px"><span style="font-size:11px;letter-spacing:.2em;color:#8fd3dc">DEIN RICHTWERT</span><br><b style="font-size:20px">${eur(lead.estimate.min)} – ${eur(lead.estimate.max)}</b></p>` : '';

const html = `<!doctype html><html lang="de"><body style="margin:0;background:#f3f5f8;font-family:'Exo 2',Segoe UI,Arial,sans-serif;color:#4a5664">
<table width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:24px 12px">
<table width="600" cellpadding="0" cellspacing="0" style="max-width:600px;background:#fff;border-radius:12px;overflow:hidden">
<tr><td style="background:#18222e;padding:28px 32px;color:#fff">
<div style="font-size:11px;letter-spacing:.22em;color:#8fd3dc;font-weight:700">TASWIQ MEDIA.</div>
<div style="font-size:26px;font-weight:800;margin-top:8px">Hallo ${lead.firstName},</div></td></tr>
<tr><td style="padding:28px 32px;font-size:15px;line-height:1.6">
<p>${INTRO[lead.industry]}</p>${estimate}${body}
<p style="margin-top:28px">Bis gleich,<br><b style="color:#1c2631">Karim Azzaoui</b><br>TasWiq Media.</p></td></tr>
<tr><td style="border-top:3px solid #5aaeb8;background:#f3f5f8;padding:16px 32px;font-size:11px;color:#5e6a78">
TasWiq Media. · ${PHONE} · <a href="${SITE_URL}" style="color:#287681">${SITE_URL.replace('https://', '')}</a></td></tr>
</table></td></tr></table></body></html>`;

// Discord-Embed (Slack: siehe Notiz im Workflow)
const color = lead.tier === 'premium' ? 0x5aaeb8 : lead.tier === 'growth' ? 0x8fd3dc : 0x9aa6b4;
const discord = {
  username: 'TasWiq Leads',
  content: lead.tier === 'premium' ? '@here Premium-Lead – bitte heute noch melden!' : undefined,
  embeds: [{
    title: `${TIER[lead.tier]} · ${lead.name}${lead.company ? ' (' + lead.company + ')' : ''}`,
    url: lead.id ? `${SITE_URL}/admin/leads/${lead.id}` : undefined,
    color,
    fields: [
      { name: 'Branche', value: INDUSTRY[lead.industry], inline: true },
      { name: 'Budget', value: lead.estimate ? `${eur(lead.estimate.min)}–${eur(lead.estimate.max)}` : BUDGET[lead.budget], inline: true },
      { name: 'Score', value: String(lead.score), inline: true },
      { name: 'Quelle', value: SOURCE[lead.source] ?? lead.source, inline: true },
      { name: 'Kontakt', value: `${lead.email}${lead.phone ? '\n' + lead.phone : ''}`, inline: true },
      { name: 'Vorhaben', value: (lead.interests ?? []).join(', ') || '–' },
      ...(lead.message ? [{ name: 'Nachricht', value: lead.message.slice(0, 1000) }] : []),
    ],
    timestamp: lead.createdAt,
  }],
};

return [{ json: { lead, meta: payload.meta ?? {}, email: { subject, html }, discord } }];
